#[test]
fn mul80_parity() {
    for (a, b, want) in MUL {
        let got = mul80(f(*a), f(*b)).to_f64().to_bits();
        assert_eq!(got, *want, "mul80 {a:#x} {b:#x}");
    }
}

#[test]
fn add80_parity() {
    for (a, b, want) in ADD {
        let got = add80(f(*a), f(*b)).to_f64().to_bits();
        assert_eq!(got, *want, "add80 {a:#x} {b:#x}");
    }
}

#[test]
fn chain_parity() {
    for (a, b, c, d, e, want) in CHAIN {
        let m1 = mul80(f(*a), f(*b));
        let m2 = mul80(f(*c), f(*d));
        let got = add80(add80(m1, m2), f(*e)).to_f64().to_bits();
        assert_eq!(got, *want);
    }
}

#[test]
fn f32_store_parity() {
    for (a, b, want) in F32MUL {
        let x = f32_round(mul80(f(*a), f(*b)).to_f64());
        assert_eq!(f32_bits(x), *want);
    }
}

#[test]
fn float_log_parity() {
    for (x, want) in LOG {
        assert_eq!(wwise_float_log(f64::from_bits(*x)).to_bits(), *want);
    }
    for (n, want) in OFF {
        assert_eq!(offset_for_n(*n).to_bits(), *want);
    }
}
